{
  "a_sentences": [
    {
      "a_text": "Le litige porte sur l'étendue de l'allocation pour impotent de l'assurance-invalidité allouée à la personne assurée, ensuite d'une révision.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Pour atteindre un degré moyen d'impotence, la personne assurée doit avoir besoin d'une aide régulière pour accomplir au moins deux actes ordinaires de la vie, en plus d'un accompagnement durable pour faire face aux nécessités de la vie.",
      "b_propositions": ["P2", "P4"]
    },
    {
      "a_text": "L'accompagnement pour faire face aux nécessités de la vie consiste en une aide complémentaire et autonome pour structurer la journée, gérer les situations quotidiennes, tenir le ménage, ou éviter un isolement durable.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Les éléments de fait justifiant une aide pour accomplir les actes ordinaires de la vie ne peuvent pas être retenus simultanément pour fonder un besoin d'accompagnement pour faire face aux nécessités de la vie.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La vérification visuelle du résultat d'un acte par un tiers n'est pas suffisante pour admettre une aide régulière, dès lors qu'elle ne requiert pas une intervention directe du tiers à la place de la personne assurée.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que la personne assurée était autonome pour se lever, s'asseoir et se coucher, mais le Tribunal fédéral constate qu'elle a besoin d'un rituel d'endormissement quotidien et d'indications pour structurer ses journées.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que la personne assurée a besoin d'une aide régulière pour accomplir deux actes ordinaires de la vie et d'un accompagnement durable pour faire face aux nécessités de la vie, ce qui ouvre le droit à une allocation pour impotent de degré moyen.",
      "b_propositions": ["P8"]
    }
  ]
}
